/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// Service class to run the update and creation of new record
/// </summary>
public class METVendOpenItemsService extends SysOperationServiceBase
{
    
    VendParameters  vendParameters = VendParameters::find();

}

Method.Source:
    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// Checks if run in batch or not.
    /// </summary>
    /// <param name = "_dataContract">Data contract</param>
    public void processOperation(METVendOpenItemsContract _dataContract)
    {
        BatchHeader                             batchHeader;
        SysOperationServiceController           controller;
        METVendOpenItemsContract                dataContract;
        Query                                   query;
        QueryBuildDataSource                    qbds, qbds1;
        QueryBuildRange                         qrPaymMode, qrVendAccountNum;
        QueryRun                                queryRun;
        VendTransOpen                           vendTransOpen;
        int                                     totalCount, bundleSize, i, j;
        RecId                                   fromRecId,toRecId;
        List                                    recList;
        
        if(!vendParameters.METpayPaymMode)
        {
            throw error("@MET:MetpayParameterNotSet");
        }
        totalCount = this.vendTransOpenRecCount(_dataContract);
        bundleSize = real2int(roundUp((totalCount / _dataContract.getNumOfTasks()), 1.0));

        query          = new Query();
        query.allowCrossCompany(true);

        if(_dataContract.getVendLegalEntityId())
        {
            query.addCompanyRange(_dataContract.getVendLegalEntityId());
        }

        // VendTransOpen -->
        qbds = query.addDataSource(tablenum(VendTransOpen));

        qbds.addSortField(fieldnum(VendTransOpen, RecId));
        qbds.orderMode(OrderMode::OrderBy);

        // VendTrans -->
        qbds = qbds.addDataSource(tablenum(VendTrans));
        qbds.relations(true);
        qbds.joinMode(JoinMode::ExistsJoin);

        if(_dataContract.getVendAccountNum())
        {
            qrVendAccountNum = qbds.addRange(fieldNum(VendTrans, AccountNum));
            qrVendAccountNum.value(_dataContract.getVendAccountNum());
        }    

        qrPaymMode = qbds.addRange(fieldnum(VendTrans, PaymMode));
        qrPaymMode.value(vendParameters.METpayPaymMode);

        // LedgerJournalTrans -->
        qbds1 = qbds.addDataSource(tablenum(LedgerJournalTrans));
        qbds1.addLink(fieldNum(VendTrans, Voucher), fieldNum(LedgerJournalTrans, Voucher));
        qbds1.joinMode(JoinMode::ExistsJoin);
        
        queryRun   = new QueryRun(query);
        
        recList = new List(Types::Int64);

        try
        {
            if (this.isExecutingInBatch())
            {
                while (queryRun.next())
                {    
                    vendTransOpen = queryRun.get(tablenum(VendTransOpen), 1);
                    
                    if (vendTransOpen)
                    {
                        i++;
                        j++;
                        recList.addEnd(vendTransOpen.RecId);

                        if (i == 1)
                        {
                            fromRecId = vendTransOpen.RecId;
                        }
                        
                        if (i >= bundleSize || j == totalCount)
                        {
                            toRecId = vendTransOpen.RecId;

                            if (!batchHeader)
                            {
                                batchHeader = this.getCurrentBatchHeader();
                            }

                            // create new controller for the runtime task
                            controller = new SysOperationServiceController(classStr(METVendOpenItemsSubTaskService), methodStr(METVendOpenItemsSubTaskService, processSubTask));
                            controller.parmDialogCaption(strFmt("@MET:VendOpenItemsServiceSubTaskDesc", fromRecId, toRecId));

                            // grab contract instance from controller
                            dataContract = controller.getDataContractObject() as METVendOpenItemsContract;
                            dataContract.getrecList(recList);
                            dataContract.getNumOfTasks(_dataContract.getNumOfTasks());
                            
                            // create subTask according to controller instance and header recid
                            batchHeader.addRuntimeTask(controller, this.getCurrentBatchTask().RecId);

                            // Resets counts. int j is not reset due to spill over of recrods at the end
                            recList = new List(Types::Int64);
                            i = 0;
                        }
                    }
                }
            }
            else
            {
                throw Error("@MET:VendOpenItemsError");
            }

            if(batchHeader)
            {
                // save the batchheader if it has been created
                batchHeader.save();
            }
            
        }
        catch
        {
            throw Error ("@MET:VendOpenItemsErrorHandler");
        }

    }

    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// </summary>
    /// <param name = "_dataContract">Data contract</param>
    /// <returns>total row count</returns>
    public counter vendTransOpenRecCount(METVendOpenItemsContract _dataContract)
    {
        VendTransOpen       vendTransOpen;
        VendTrans           vendTrans;

        if(_dataContract.getVendAccountNum())
        {
            select crosscompany count(RecId)
                from vendTransOpen
                where vendTransOpen.DataAreaId == _dataContract.getVendLegalEntityId()
                && vendTransOpen.AccountNum == _dataContract.getVendAccountNum()
                exists join vendTrans
                where vendTrans.RecId == vendTransOpen.RefRecID
                && VendTrans.PaymMode   == vendParameters.METpayPaymMode;
        }
        else if(_dataContract.getVendLegalEntityId())
        {
            select crosscompany count(RecId)
                from vendTransOpen
                where vendTransOpen.DataAreaId == _dataContract.getVendLegalEntityId()
                exists join vendTrans
                where vendTrans.RecId == vendTransOpen.RefRecID
                && VendTrans.PaymMode   == vendParameters.METpayPaymMode;
        }
        else
        {
            select crosscompany count(RecId)
                from vendTransOpen
                exists join vendTrans
                where vendTrans.RecId == vendTransOpen.RefRecID
                && VendTrans.PaymMode   == vendParameters.METpayPaymMode;
        }
        return int642int(vendTransOpen.RecId);
    }
